	for plantilla_id in plantilla_ids:
		plantilla = Entrenamiento.objects.get(pk=plantilla_id)
		plantilla.es_plantilla = True
		plantilla.save(update_fields=["es_plantilla"])
		entradas = list(
			EntrenamientoEjercicio.objects.filter(entrenamiento=plantilla).order_by("orden", "pk")
		)
		asignaciones = list(
			UsuarioEntrenamiento.objects.filter(entrenamiento=plantilla).order_by("pk")
		)
		for asignacion in asignaciones:
			copia = Entrenamiento.objects.create(
				nombre=plantilla.nombre,
				descripcion=plantilla.descripcion,
				es_plantilla=False,
				plantilla_id=plantilla.pk,
			)
			entradas_por_id = {}
			entradas_por_ejercicio = {}
			for entrada in entradas:
				entrada_personal = EntrenamientoEjercicio.objects.create(
					entrenamiento=copia,
					ejercicio_id=entrada.ejercicio_id,
					orden=entrada.orden,
				)
				entradas_por_id[entrada.pk] = entrada_personal
				entradas_por_ejercicio[entrada.ejercicio_id] = entrada_personal
			for seleccion in UsuarioEntrenamientoEjercicio.objects.filter(
				usuario_entrenamiento=asignacion
			):
				entrada_personal = entradas_por_id.get(seleccion.entrenamiento_ejercicio_id)
				if entrada_personal is None:
					entrada_original = EntrenamientoEjercicio.objects.get(
						pk=seleccion.entrenamiento_ejercicio_id
					)
					entrada_personal = entradas_por_ejercicio.get(
						entrada_original.ejercicio_id
					)
					if entrada_personal is None:
						ultimo_orden = max(
							(entrada.orden for entrada in entradas_por_ejercicio.values()),
							default=0,
						)
						entrada_personal = EntrenamientoEjercicio.objects.create(
							entrenamiento=copia,
							ejercicio_id=entrada_original.ejercicio_id,
							orden=ultimo_orden + 1,
						)
						entradas_por_ejercicio[entrada_original.ejercicio_id] = entrada_personal
				seleccion.entrenamiento_ejercicio_id = entrada_personal.pk
				seleccion.save(update_fields=["entrenamiento_ejercicio"])
			asignacion.entrenamiento_id = copia.pk
			asignacion.save(update_fields=["entrenamiento"])


